+			var dataReEncrypted []byte
+			var enc common.EncryptMarshaller
+			if dataReEncrypted, err = enc.Marshal(obj); err == nil {
+				if err = nvJsonUnmarshal(key, dataReEncrypted, obj); err == nil {
